/* Personale di gruppo: identità esplicite, assegnazioni e decorrenze. */
let workforceGroup='',workforceOn=new Date().toLocaleDateString('sv-SE'),workforceRequest=0,workforceList=null,workforceDetail=null;
const wfDate=v=>v?new Date(v+'T12:00:00').toLocaleDateString('it-IT'):'senza fine';
const wfRange=r=>wfDate(r.effective_from)+' → '+wfDate(r.effective_to);
const wfRole=()=>['admin','hr','manager'].includes(auth?.user?.role);

async function renderWorkforce(){
 if(!wfRole())throw Error('Pagina riservata a HR e responsabili.');
 const request=++workforceRequest,selected=workforceGroup;
 const data=await api('workforce?on='+encodeURIComponent(workforceOn)+(selected?'&gid='+encodeURIComponent(selected):''));
 if(request!==workforceRequest||tab!=='gruppo')return;
 $('#centerSelect').hidden=true;$('#monthPick').closest('.actions').hidden=true;
 document.querySelector('main .heading .eyebrow').textContent='ARCHIVIO HR · '+data.scope.toUpperCase();
 document.querySelector('main .heading .muted').textContent='Identità, sedi e storico delle condizioni';
 if(selected){workforceDetail=data.groups[0];wfRenderDetail(workforceDetail);return}
 workforceList=data;workforceDetail=null;
 $('#content').innerHTML=`<section class="panel"><div class="toolbar"><div><h2>Persone e assegnazioni</h2><p class="muted smalltext">Le anagrafiche esistenti hanno identità distinte. I collegamenti tra centri richiedono una verifica esplicita.</p></div><div class="actions"><label class="smalltext" for="workforceOn">Situazione al</label><input id="workforceOn" type="date" value="${esc(workforceOn)}"><input id="workforceSearch" placeholder="Cerca nome, matricola, centro" aria-label="Cerca personale"></div></div><div id="workforceRows"></div></section><p class="footer-note">Fascicoli e allegati conservano il centro di origine. I responsabili vedono solo le sedi assegnate; HR centrale consulta tutto il gruppo.</p>`;
 $('#workforceOn').onchange=e=>{if(e.target.value){workforceOn=e.target.value;renderWorkforce().catch(x=>toast(x.message))}};
 const rows=()=>{const q=$('#workforceSearch').value.toLocaleLowerCase();$('#workforceRows').innerHTML=`<div class="table-scroll"><table class="data-table"><thead><tr><th>Persona</th><th>Assegnazioni visibili</th><th>Ruoli alla data</th><th></th></tr></thead><tbody>${data.groups.filter(g=>g.assignments.some(a=>[a.person.name,a.person.registration,a.center_name].join(' ').toLocaleLowerCase().includes(q))).map(g=>`<tr><td><b>${esc(g.assignments[0].person.name)}</b><small class="hr-secondary wf-identity">ID ${esc(g.global_id)}</small></td><td>${g.assignments.map(a=>`<div>${esc(a.center_name)} <small class="muted">${esc(a.person.registration||'senza matricola')}</small></div>`).join('')}</td><td>${g.assignments.map(a=>`<div>${esc(a.person.role)}${a.person.effective_contract?'':' · anagrafica corrente'}</div>`).join('')}</td><td><button class="btn small" data-wf-group="${esc(g.global_id)}">Apri persona</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessuna persona disponibile. Crea le anagrafiche dalla pagina Dipendenti.</td></tr>'}</tbody></table></div>`;document.querySelectorAll('[data-wf-group]').forEach(b=>b.onclick=()=>{workforceGroup=b.dataset.wfGroup;renderWorkforce().catch(x=>toast(x.message))})};
 $('#workforceSearch').oninput=rows;rows();
}

function wfRenderDetail(g){
 $('#content').innerHTML=`<div class="toolbar"><div class="actions"><button class="btn" id="workforceBack">← Elenco persone</button><span class="tag">${g.assignments.length} assegnazioni visibili</span></div><div class="field"><label for="workforceOn">Confronta la situazione al</label><input type="date" id="workforceOn" value="${esc(workforceOn)}"></div></div><p class="smalltext muted wf-identity">Identità di gruppo ${esc(g.global_id)}</p><div class="wf-assignments">${g.assignments.map((a,i)=>`<section class="panel wf-assignment"><div class="toolbar"><div><div class="eyebrow">${esc(a.center_name)}</div><h2>${esc(a.person.name)}</h2><p class="muted smalltext">${esc(a.person.registration||'Senza matricola')} · ${esc(a.person.role)} · ${a.person.active?'Attivo':'Inattivo'}</p></div><div class="actions"><button class="btn" data-wf-hr="${i}">Fascicolo HR</button><button class="btn" data-wf-link="${i}">Collega identità</button>${g.assignments.length>1?`<button class="btn" data-wf-unlink="${i}">Separa identità</button>`:''}</div></div><div class="note">${a.person.effective_contract?`Al ${wfDate(workforceOn)}: ${esc(a.person.contract_type||'Tipo da specificare')} · ${a.person.weekly_hours} ore/settimana · part-time ${a.person.part_time_percent}%.`: 'Nessun contratto con decorrenza verificata a questa data. Il ruolo mostrato è quello dell’anagrafica corrente; lo storico precedente non viene dedotto.'}</div><div class="toolbar"><h3>Contratti e decorrenze</h3><button class="btn small" data-wf-contract="${i}">+ Decorrenza contratto</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Validità inclusiva</th><th>Condizioni</th><th>Versione</th><th></th></tr></thead><tbody>${a.contracts.map((r,j)=>`<tr><td>${wfRange(r)}</td><td>${esc(r.data.role)} · ${esc(r.data.contract_type)}<small class="hr-secondary">${r.data.weekly_hours} ore · ${r.data.part_time_percent}% · ${esc(r.data.ccnl)} ${esc(r.data.level)}</small></td><td>${r.version}</td><td><button class="btn small" data-wf-edit-contract="${i}:${j}">Modifica</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessuna decorrenza registrata.</td></tr>'}</tbody></table></div><div class="toolbar"><h3>Condizioni economiche</h3><div class="actions"><button class="btn small" data-wf-economics="${i}">+ Decorrenza economica</button><button class="btn small" data-wf-preview="${i}">Anteprima e applica al mese</button></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Validità inclusiva</th><th>Modello</th><th>Tariffe / quota</th><th></th></tr></thead><tbody>${a.economics.map((r,j)=>`<tr><td>${wfRange(r)}</td><td>${esc({turns:'Turni',hours:'Ore',fixed:'Quota fissa'}[r.data.model])}<small class="hr-secondary">${r.data.confirmed?'Confermato':'Da confermare'} · v${r.version}</small></td><td>€ ${r.data.weekday_rate} / € ${r.data.holiday_rate}<small class="hr-secondary">Quota fissa € ${r.data.fixed_amount}</small></td><td><button class="btn small" data-wf-edit-economic="${i}:${j}">Modifica</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Gli accordi mensili esistenti restano disponibili in Accordi e calcoli.</td></tr>'}</tbody></table></div><details class="wf-history"><summary>Allegati del centro (${a.documents.length})</summary>${a.documents.map(d=>`<p>${esc(d.name)} · ${esc(d.category)} <small class="muted">Caricato da ${esc(d.uploaded_by)}</small> <a class="btn small" href="/api/hr_document_view?cid=${encodeURIComponent(a.cid)}&amp;id=${encodeURIComponent(d.id)}" target="_blank" rel="noopener noreferrer">Visualizza</a></p>`).join('')||'<p class="muted">Nessun allegato.</p>'}</details><details class="wf-history"><summary>Storico delle modifiche (${a.history.length})</summary>${a.history.map(h=>`<details class="wf-history-entry"><summary>${esc(h.kind)} · ${esc(new Date(h.stamp).toLocaleString('it-IT'))} · ${esc(h.actor)}</summary><p>${esc(h.reason)}</p><div class="wf-compare"><div><b>Prima</b><pre>${esc(JSON.stringify(JSON.parse(h.before_data),null,2))}</pre></div><div><b>Dopo</b><pre>${esc(JSON.stringify(JSON.parse(h.after_data),null,2))}</pre></div></details>`).join('')||'<p class="muted">Nessuna modifica registrata.</p>'}</details></section>`).join('')}</div>`;
 $('#workforceBack').onclick=()=>{workforceGroup='';renderWorkforce().catch(x=>toast(x.message))};$('#workforceOn').onchange=e=>{if(e.target.value){workforceOn=e.target.value;renderWorkforce().catch(x=>toast(x.message))}};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.onclick=()=>fn(b));
 bind('[data-wf-hr]',async b=>{const a=g.assignments[+b.dataset.wfHr];cid=a.cid;hrData=null;hrList=null;hrDirty=false;try{await load();hrPid=a.pid;hrSection='anagrafica';tab='dipendenti';render()}catch(x){toast(x.message)}});
 bind('[data-wf-link]',b=>wfLink(g.assignments[+b.dataset.wfLink],false).catch(x=>toast(x.message)));
 bind('[data-wf-unlink]',b=>wfLink(g.assignments[+b.dataset.wfUnlink],true).catch(x=>toast(x.message)));
 bind('[data-wf-contract]',b=>wfInterval(g.assignments[+b.dataset.wfContract],null,false));
 bind('[data-wf-economics]',b=>wfInterval(g.assignments[+b.dataset.wfEconomics],null,true));
 bind('[data-wf-edit-contract]',b=>{const [i,j]=b.dataset.wfEditContract.split(':').map(Number);wfInterval(g.assignments[i],g.assignments[i].contracts[j],false)});
 bind('[data-wf-edit-economic]',b=>{const [i,j]=b.dataset.wfEditEconomic.split(':').map(Number);wfInterval(g.assignments[i],g.assignments[i].economics[j],true)});
 bind('[data-wf-preview]',b=>wfPreview(g.assignments[+b.dataset.wfPreview]));

}

async function wfLink(a,separate){
 const data=separate?null:await api('workforce');
 const choices=data?.groups.filter(g=>g.global_id!==workforceGroup&&!g.assignments.some(x=>x.cid===a.cid))||[];
 modal(separate?'Separa questa assegnazione':'Collega alla stessa persona',`<p>${esc(a.person.name)} · ${esc(a.center_name)}</p><div class="note">${separate?'Verrà creata una nuova identità di gruppo per questa sede.':'Verifica l’identità tramite i fascicoli prima di collegare. Nome e matricola uguali non bastano.'} I fascicoli, gli allegati e le presenze restano nei centri di origine.</div>${separate?'':`<div class="field"><label for="wfTarget">Identità da mantenere</label><select id="wfTarget"><option value="">Seleziona persona</option>${choices.map(g=>`<option value="${esc(g.global_id)}">${esc(g.assignments[0].person.name)} · ${esc(g.assignments.map(x=>x.center_name).join(', '))} · ID ${esc(g.global_id.slice(0,8))}</option>`).join('')}</select></div>`}<div class="field"><label for="wfReason">Motivazione e verifica effettuata</label><textarea id="wfReason" minlength="8" maxlength="1000"></textarea></div>`,'<button class="btn primary" id="wfLinkSave">'+(separate?'Separa':'Collega')+'</button>');
 $('#wfLinkSave').onclick=async()=>{const btn=$('#wfLinkSave');btn.disabled=true;try{const target=separate?null:choices.find(g=>g.global_id===$('#wfTarget').value);if(!separate&&!target)throw Error('Seleziona l’identità verificata.');const r=await api('workforce_link',{cid:a.cid,pid:a.pid,assignment_version:a.version,global_id:target?.global_id||'',target_version:target?.version,reason:$('#wfReason').value});$('#modal').close();workforceGroup=r.global_id;await renderWorkforce();toast('Identità aggiornata; fascicoli conservati.')}catch(e){modalError(e);btn.disabled=false}};
}

function wfInterval(a,r,economic){
 const d=r?.data||(economic?a.economic_proposal:{role:a.person.role,contract_type:a.person.contract_type||a.person.contract||'',ccnl:'',level:'',weekly_hours:'',part_time_percent:'',note:''});
 const input=(id,label,value,type='text',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;
 const numeric={theoretical_units:'Unità teoriche manuali',hours_per_day:'Ore teoriche giornaliere',weekday_rate:'Tariffa feriale €',holiday_rate:'Tariffa festiva €',fixed_amount:'Quota fissa €',fixed_deduction:'Detrazione fissa €',adjustment:'Conguaglio €',ccnl_rate:'Quota CCNL festivi €',ccnl_count:'Festivi già riconosciuti'};
 const select=(id,label,values,value)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}">${Object.entries(values).map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
 const economics=()=>select('wfModel','Modello',{turns:'Turni',hours:'Ore',fixed:'Quota fissa'},d.model)+select('wfBasis','Base',{all:'Tutte le unità',surplus:'Eccedenza sul teorico'},d.basis)+select('wfTheoretical','Teorico',{calendar:'Calendario del mese',manual:'Unità manuali'},d.theoretical_mode)+Object.entries(numeric).map(([k,l])=>input('wfN_'+k,l,d[k],'number',`step="${k==='ccnl_count'?'1':'any'}" ${k==='adjustment'?'':'min="0"'}`)).join('')+`<div class="field full"><label for="wfAbsences">Causali assenza conteggiabili · codici separati da virgola</label><input id="wfAbsences" value="${esc(d.counted_absences.join(', '))}"></div><label class="check"><input id="wfExternal" type="checkbox" ${d.include_external?'checked':''}>Include lavoro esterno</label><label class="check"><input id="wfConfirmed" type="checkbox" ${d.confirmed?'checked':''}>Condizioni verificate e confermate</label>`;
 const contract=()=>select('wfRole','Ruolo',Object.fromEntries(a.roles.map(x=>[x,x])),d.role)+input('wfType','Tipo contratto',d.contract_type)+input('wfCcnl','CCNL',d.ccnl)+input('wfLevel','Livello',d.level)+input('wfHours','Ore settimanali',d.weekly_hours,'number','min="0.01" max="168" step="any"')+input('wfPartTime','Percentuale part-time (100 = tempo pieno)',d.part_time_percent,'number','min="0.01" max="100" step="any"')+`<div class="field full"><label for="wfNote">Note contratto</label><textarea id="wfNote" maxlength="2000">${esc(d.note)}</textarea></div>`;
 modal((r?'Modifica':'Nuova')+' decorrenza '+(economic?'economica':'contrattuale'),`<p>${esc(a.person.name)} · ${esc(a.center_name)}</p><div class="note">Le date iniziale e finale sono incluse. Per un cambio dal 16, chiudi la vecchia validità al 15. ${economic?'Il salvataggio non modifica gli accordi mensili: usa poi Anteprima e applica al mese.':'Inserisci decorrenze verificate; i dati precedenti non sono ricostruiti automaticamente.'}</div><div class="formgrid">${input('wfFrom','Valido dal',r?.effective_from||workforceOn,'date')}${input('wfTo','Valido fino al · vuoto = senza fine',r?.effective_to||'','date')}${economic?economics():contract()}<div class="field full"><label for="wfReason">Motivazione della registrazione / modifica</label><textarea id="wfReason" minlength="8" maxlength="1000"></textarea></div></div>`,'<button class="btn primary" id="wfIntervalSave">Salva decorrenza</button>');
 $('#wfIntervalSave').onclick=async()=>{const btn=$('#wfIntervalSave');btn.disabled=true;try{const data=economic?{...d,model:$('#wfModel').value,basis:$('#wfBasis').value,theoretical_mode:$('#wfTheoretical').value,...Object.fromEntries(Object.keys(numeric).map(k=>[k,Number($('#wfN_'+k).value)])),counted_absences:$('#wfAbsences').value.split(',').map(x=>x.trim()).filter(Boolean),include_external:$('#wfExternal').checked,confirmed:$('#wfConfirmed').checked}:{role:$('#wfRole').value,contract_type:$('#wfType').value,ccnl:$('#wfCcnl').value,level:$('#wfLevel').value,weekly_hours:Number($('#wfHours').value),part_time_percent:Number($('#wfPartTime').value),note:$('#wfNote').value};await api(economic?'workforce_economic':'workforce_contract',{cid:a.cid,pid:a.pid,assignment_version:a.version,id:r?.id,version:r?.version||0,effective_from:$('#wfFrom').value,effective_to:$('#wfTo').value,data,reason:$('#wfReason').value});$('#modal').close();await renderWorkforce();toast('Decorrenza salvata e registrata nello storico.')}catch(e){modalError(e);btn.disabled=false}};
}

function wfPreview(a){
 modal('Anteprima condizioni economiche',`<p>${esc(a.person.name)} · ${esc(a.center_name)}</p><div class="field"><label for="wfPreviewMonth">Mese</label><input id="wfPreviewMonth" type="month" value="${esc(month)}"></div><button class="btn" id="wfPreviewLoad">Calcola anteprima</button><div id="wfPreviewResult" aria-live="polite"></div>`);
 $('#wfPreviewLoad').onclick=async()=>{try{const m=$('#wfPreviewMonth').value,p=await api(`workforce_preview?cid=${encodeURIComponent(a.cid)}&pid=${encodeURIComponent(a.pid)}&month=${encodeURIComponent(m)}`);$('#wfPreviewResult').innerHTML=`<p>${p.segments.length} intervalli nel mese selezionato.</p>${p.manual_required?`<div class="note">${esc(p.message)}</div>`:`<p><b>Risultato: ${p.result.amount===null?'non calcolabile':'€ '+p.result.amount.toFixed(2)}</b> · ${esc(p.result.status)}</p>${p.result.warnings.map(w=>`<p class="note">${esc(w)}</p>`).join('')}`}${p.current_agreement?'<p class="muted smalltext">È già presente un accordo mensile: applicando, la nuova versione sostituirà quella corrente mantenendo lo storico.</p>':''}${p.closed?'<div class="note">Mese chiuso: applicazione non disponibile.</div>':p.manual_required?'':`<div class="field"><label for="wfApplyReason">Motivazione dell’applicazione al mese</label><textarea id="wfApplyReason" minlength="8" maxlength="1000"></textarea></div><button class="btn primary" id="wfApply">Applica condizioni al mese ${esc(m)}</button>`}`;if($('#wfApply'))$('#wfApply').onclick=async()=>{const btn=$('#wfApply');btn.disabled=true;try{await api('workforce_apply',{cid:a.cid,pid:a.pid,assignment_version:a.version,month:m,revision:p.revision,reason:$('#wfApplyReason').value});$('#modal').close();await renderWorkforce();toast('Accordo mensile aggiornato. Verifica nuovamente il mese.')}catch(e){modalError(e);btn.disabled=false}}}catch(e){modalError(e)}};
}
